/* CSS PART 1 OF 4 */

/* =========================================
   1. DESIGN TOKENS
   Original visual direction:
   Refined craftsmanship / residential renovation
   ========================================= */

:root {
  color-scheme: light;

  /* Brand palette */
  --color-ink: #242824;
  --color-ink-soft: #414740;
  --color-paper: #f7f6f2;
  --color-white: #ffffff;
  --color-surface: #eeede7;
  --color-surface-dark: #303630;

  /* Warm construction accent */
  --color-accent: #c47745;
  --color-accent-hover: #a95e32;
  --color-accent-light: #ead6c5;

  /* Supporting colors */
  --color-muted: #777970;
  --color-border: #deddd5;
  --color-border-dark: #50564f;
  --color-success: #526b53;

  /* Typography */
  --font-heading: "Georgia", "Times New Roman", serif;
  --font-body: "Helvetica Neue", Helvetica, Arial, sans-serif;

  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.375rem;
  --text-2xl: clamp(1.75rem, 3vw, 2.5rem);
  --text-3xl: clamp(2.5rem, 5vw, 4.25rem);
  --text-hero: clamp(3rem, 6.5vw, 6rem);

  --line-tight: 1.05;
  --line-heading: 1.15;
  --line-body: 1.75;

  /* Layout */
  --container-width: 1240px;
  --container-narrow: 850px;
  --page-gutter: clamp(1.25rem, 5vw, 5rem);
  --section-space: clamp(4.5rem, 9vw, 8.5rem);
  --section-space-small: clamp(3rem, 6vw, 5rem);

  /* Spacing */
  --space-1: 0.375rem;
  --space-2: 0.75rem;
  --space-3: 1rem;
  --space-4: 1.5rem;
  --space-5: 2rem;
  --space-6: 3rem;
  --space-7: 4rem;
  --space-8: 5rem;

  /* Borders and surfaces */
  --radius-small: 4px;
  --radius-medium: 8px;
  --radius-large: 14px;
  --radius-pill: 999px;

  --shadow-soft: 0 12px 35px rgba(36, 40, 36, 0.07);
  --shadow-elevated: 0 20px 55px rgba(36, 40, 36, 0.13);

  /* Motion */
  --transition-fast: 180ms ease;
  --transition-normal: 280ms ease;

  /* Navigation */
  --nav-height: 86px;
}


/* =========================================
   2. RESET AND GLOBAL FOUNDATIONS
   ========================================= */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: calc(var(--nav-height) + 1rem);
  -webkit-text-size-adjust: 100%;
}

body {
  min-width: 320px;
  margin: 0;
  background: var(--color-paper);
  color: var(--color-ink);
  font-family: var(--font-body);
  font-size: var(--text-base);
  font-weight: 400;
  line-height: var(--line-body);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body,
button,
input,
select,
textarea {
  font-family: var(--font-body);
}

button,
input,
select,
textarea {
  font-size: inherit;
}

button {
  cursor: pointer;
}

img,
picture,
video,
svg {
  display: block;
  max-width: 100%;
}

img {
  height: auto;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
select,
textarea {
  border-radius: 0;
}

ul,
ol {
  padding-left: 1.35rem;
}

p,
h1,
h2,
h3,
h4,
h5,
h6 {
  margin-top: 0;
}

p:last-child {
  margin-bottom: 0;
}

::selection {
  background: var(--color-accent);
  color: var(--color-white);
}


/* =========================================
   3. ACCESSIBILITY FOUNDATIONS
   ========================================= */

:focus {
  outline: none;
}

:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 4px;
}

.skip-link {
  position: absolute;
  z-index: 9999;
  top: 0.75rem;
  left: 0.75rem;
  padding: 0.8rem 1.2rem;
  transform: translateY(-160%);
  background: var(--color-ink);
  color: var(--color-white);
  font-size: var(--text-sm);
  font-weight: 700;
  transition: transform var(--transition-fast);
}

.skip-link:focus {
  transform: translateY(0);
}

[hidden] {
  display: none !important;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}


/* =========================================
   4. TYPOGRAPHY SYSTEM
   ========================================= */

h1,
h2,
h3,
h4,
h5,
h6 {
  margin-bottom: 1.1rem;
  color: var(--color-ink);
  font-family: var(--font-heading);
  font-weight: 400;
  letter-spacing: -0.035em;
  line-height: var(--line-heading);
}

h1 {
  font-size: var(--text-hero);
  letter-spacing: -0.055em;
  line-height: var(--line-tight);
}

h2 {
  font-size: var(--text-3xl);
}

h3 {
  font-size: var(--text-2xl);
}

h4 {
  font-size: var(--text-xl);
}

h5 {
  font-size: var(--text-lg);
}

h6 {
  font-size: var(--text-base);
}

p {
  margin-bottom: 1.35rem;
  color: var(--color-muted);
  font-size: var(--text-base);
  line-height: var(--line-body);
}

strong,
b {
  color: var(--color-ink);
  font-weight: 700;
}

small,
.text-small {
  font-size: var(--text-sm);
}

.eyebrow,
.section-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 1.25rem;
  color: var(--color-accent);
  font-size: var(--text-xs);
  font-weight: 700;
  letter-spacing: 0.16em;
  line-height: 1.5;
  text-transform: uppercase;
}

.eyebrow::before,
.section-eyebrow::before {
  width: 28px;
  height: 1px;
  background: currentColor;
  content: "";
}

.text-lead {
  max-width: 660px;
  font-size: clamp(1.05rem, 1.6vw, 1.25rem);
  line-height: 1.8;
}

.text-muted {
  color: var(--color-muted);
}

.text-light {
  color: rgba(255, 255, 255, 0.76);
}

.text-accent {
  color: var(--color-accent);
}


/* =========================================
   5. PAGE GRID AND SHARED CONTAINERS
   ========================================= */

.site-wrapper {
  width: 100%;
  overflow: clip;
}

.container {
  width: min(
    calc(100% - (var(--page-gutter) * 2)),
    var(--container-width)
  );
  margin-inline: auto;
}

.container-narrow {
  width: min(
    calc(100% - (var(--page-gutter) * 2)),
    var(--container-narrow)
  );
  margin-inline: auto;
}

.section {
  position: relative;
  padding-block: var(--section-space);
}

.section--compact {
  padding-block: var(--section-space-small);
}

.section--light {
  background: var(--color-paper);
}

.section--white {
  background: var(--color-white);
}

.section--soft {
  background: var(--color-surface);
}

.section--dark {
  background: var(--color-surface-dark);
  color: var(--color-white);
}

.section--dark h1,
.section--dark h2,
.section--dark h3,
.section--dark h4 {
  color: var(--color-white);
}

.section--dark p {
  color: rgba(255, 255, 255, 0.72);
}

.section-heading {
  max-width: 760px;
  margin-bottom: clamp(2.5rem, 5vw, 4.5rem);
}

.section-heading p {
  max-width: 620px;
}

.section-heading--center {
  margin-inline: auto;
  text-align: center;
}

.section-heading--center .eyebrow {
  justify-content: center;
}

.section-heading--center p {
  margin-inline: auto;
}


/* =========================================
   6. SHARED LAYOUT UTILITIES
   ========================================= */

.grid {
  display: grid;
  gap: var(--space-5);
}

.grid-2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.grid-3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.grid-4 {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.split-layout {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: center;
  gap: clamp(2.5rem, 6vw, 6rem);
}

.split-layout--wide {
  grid-template-columns: 1.15fr 0.85fr;
}

.split-layout--reverse {
  grid-template-columns: 0.85fr 1.15fr;
}

.stack {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.inline-flex {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
}

.flex-between {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}

.center-content {
  display: flex;
  align-items: center;
  justify-content: center;
}

.align-start {
  align-items: flex-start;
}

.full-width {
  width: 100%;
}

.relative {
  position: relative;
}


/* =========================================
   7. IMAGE FOUNDATIONS
   ========================================= */

.image-frame {
  position: relative;
  overflow: hidden;
  background: var(--color-surface);
}

.image-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.image-cover {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.image-natural {
  width: 100%;
  height: auto;
  object-fit: contain;
}

.image-rounded {
  overflow: hidden;
  border-radius: var(--radius-medium);
}

.image-caption {
  margin-top: 0.75rem;
  color: var(--color-muted);
  font-size: var(--text-xs);
  line-height: 1.6;
}


/* =========================================
   8. SHARED VISUAL DIVIDERS
   ========================================= */

.rule {
  width: 100%;
  height: 1px;
  border: 0;
  background: var(--color-border);
}

.rule--dark {
  background: var(--color-border-dark);
}

.accent-rule {
  width: 48px;
  height: 3px;
  background: var(--color-accent);
}
