/* CSS PART 2 OF 4 */

/* =========================================
   1. SITE HEADER
   ========================================= */

.site-header {
  position: relative;
  z-index: 1000;
  width: 100%;
  background: var(--color-white);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: flex;
  width: min(
    calc(100% - (var(--page-gutter) * 2)),
    var(--container-width)
  );
  min-height: var(--nav-height);
  margin-inline: auto;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}

.site-header--sticky {
  position: sticky;
  top: 0;
}

/* =========================================
   2. BRAND AND LOGO
   ========================================= */

.site-brand {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 0.85rem;
  min-width: 0;
  color: var(--color-ink);
}

.site-brand img {
  width: auto;
  max-width: 190px;
  max-height: 66px;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.brand-name {
  margin: 0;
  color: var(--color-ink);
  font-family: var(--font-heading);
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: -0.035em;
  line-height: 1.15;
}

.brand-description {
  margin: 0;
  color: var(--color-muted);
  font-size: 0.65rem;
  font-weight: 600;
  letter-spacing: 0.11em;
  line-height: 1.4;
  text-transform: uppercase;
}

/* =========================================
   3. DESKTOP NAVIGATION
   ========================================= */

.primary-navigation {
  display: flex;
  align-items: center;
  gap: clamp(1rem, 2vw, 2rem);
}

.primary-navigation ul {
  display: flex;
  align-items: center;
  gap: clamp(1rem, 1.8vw, 1.75rem);
  margin: 0;
  padding: 0;
  list-style: none;
}

.primary-navigation li {
  position: relative;
  margin: 0;
  padding: 0;
}

.primary-navigation a {
  display: inline-flex;
  min-height: 44px;
  align-items: center;
  color: var(--color-ink-soft);
  font-size: var(--text-sm);
  font-weight: 600;
  transition: color var(--transition-fast);
}

.primary-navigation a:hover,
.primary-navigation a[aria-current="page"] {
  color: var(--color-accent-hover);
}

.primary-navigation a:focus-visible {
  border-radius: var(--radius-small);
}

/* Dropdown navigation */

.nav-dropdown {
  position: relative;
}

.nav-dropdown > button {
  display: inline-flex;
  min-height: 44px;
  align-items: center;
  gap: 0.45rem;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--color-ink-soft);
  font-size: var(--text-sm);
  font-weight: 600;
}

.nav-dropdown > button:hover,
.nav-dropdown > button[aria-expanded="true"] {
  color: var(--color-accent-hover);
}

.nav-dropdown-menu {
  position: absolute;
  z-index: 20;
  top: calc(100% + 0.5rem);
  left: 0;
  display: none;
  width: 235px;
  padding: 0.65rem;
  border: 1px solid var(--color-border);
  background: var(--color-white);
  box-shadow: var(--shadow-elevated);
  list-style: none;
}

.nav-dropdown:hover .nav-dropdown-menu,
.nav-dropdown:focus-within .nav-dropdown-menu,
.nav-dropdown-menu.is-open {
  display: block;
}

.nav-dropdown-menu a {
  display: flex;
  width: 100%;
  min-height: 42px;
  padding: 0.55rem 0.75rem;
  border-radius: var(--radius-small);
}

.nav-dropdown-menu a:hover {
  background: var(--color-surface);
}

/* =========================================
   4. HEADER CONTACT ACTIONS
   ========================================= */

.header-actions {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 1rem;
}

.header-phone {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  color: var(--color-ink);
  line-height: 1.3;
}

.header-phone-label {
  color: var(--color-muted);
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.header-phone a {
  font-size: 0.95rem;
  font-weight: 700;
}

.header-phone a:hover {
  color: var(--color-accent-hover);
}

/* =========================================
   5. BUTTON SYSTEM
   ========================================= */

.button,
button.button {
  display: inline-flex;
  min-height: 52px;
  align-items: center;
  justify-content: center;
  gap: 0.65rem;
  padding: 0.9rem 1.55rem;
  border: 1px solid transparent;
  border-radius: var(--radius-small);
  background: var(--color-accent);
  color: var(--color-white);
  font-family: var(--font-body);
  font-size: var(--text-sm);
  font-weight: 700;
  letter-spacing: 0.015em;
  line-height: 1.2;
  text-align: center;
  transition:
    background var(--transition-fast),
    border-color var(--transition-fast),
    color var(--transition-fast),
    transform var(--transition-fast);
}

.button:hover,
button.button:hover {
  transform: translateY(-2px);
  border-color: var(--color-accent-hover);
  background: var(--color-accent-hover);
  color: var(--color-white);
}

.button:active {
  transform: translateY(0);
}

.button:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 4px;
}

.button--dark {
  border-color: var(--color-ink);
  background: var(--color-ink);
  color: var(--color-white);
}

.button--dark:hover {
  border-color: var(--color-ink-soft);
  background: var(--color-ink-soft);
}

.button--outline {
  border-color: var(--color-ink);
  background: transparent;
  color: var(--color-ink);
}

.button--outline:hover {
  border-color: var(--color-ink);
  background: var(--color-ink);
  color: var(--color-white);
}

.button--light {
  border-color: var(--color-white);
  background: var(--color-white);
  color: var(--color-ink);
}

.button--light:hover {
  border-color: var(--color-accent-light);
  background: var(--color-accent-light);
  color: var(--color-ink);
}

.button--small {
  min-height: 44px;
  padding: 0.7rem 1.15rem;
  font-size: var(--text-xs);
}

.button--large {
  min-height: 60px;
  padding: 1.1rem 2rem;
}

.button--block {
  width: 100%;
}

/* =========================================
   6. MOBILE NAVIGATION CONTROLS
   ========================================= */

.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 5px;
  padding: 0.6rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-small);
  background: var(--color-white);
  color: var(--color-ink);
  cursor: pointer;
}

.menu-toggle span {
  display: block;
  width: 21px;
  height: 2px;
  border-radius: 2px;
  background: currentColor;
  transition:
    transform var(--transition-fast),
    opacity var(--transition-fast);
}

.menu-toggle[aria-expanded="true"] span:first-child {
  transform: translateY(7px) rotate(45deg);
}

.menu-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}

.menu-toggle[aria-expanded="true"] span:last-child {
  transform: translateY(-7px) rotate(-45deg);
}

/* =========================================
   7. HERO SECTION
   ========================================= */

.hero {
  position: relative;
  display: grid;
  min-height: min(780px, calc(100svh - var(--nav-height)));
  align-items: center;
  overflow: hidden;
  isolation: isolate;
  background: var(--color-surface-dark);
  color: var(--color-white);
}

.hero-background {
  position: absolute;
  z-index: -2;
  inset: 0;
  overflow: hidden;
}

.hero-background img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 52%;
}

.hero-background::after {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(26, 31, 27, 0.94) 0%,
      rgba(26, 31, 27, 0.79) 43%,
      rgba(26, 31, 27, 0.28) 100%
    );
  content: "";
}

.hero-content {
  position: relative;
  z-index: 1;
  width: min(
    calc(100% - (var(--page-gutter) * 2)),
    var(--container-width)
  );
  margin-inline: auto;
  padding-block: clamp(5rem, 10vw, 9rem);
}

.hero-copy {
  max-width: 760px;
}

.hero .eyebrow {
  color: #e6b18a;
}

.hero h1 {
  max-width: 850px;
  margin-bottom: 1.6rem;
  color: var(--color-white);
}

.hero h1 em {
  color: #e6b18a;
  font-weight: 400;
}

.hero-description {
  max-width: 600px;
  margin-bottom: 2.25rem;
  color: rgba(255, 255, 255, 0.84);
  font-size: clamp(1.05rem, 1.6vw, 1.2rem);
  line-height: 1.8;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem;
}

.hero .button--outline {
  border-color: rgba(255, 255, 255, 0.65);
  color: var(--color-white);
}

.hero .button--outline:hover {
  border-color: var(--color-white);
  background: var(--color-white);
  color: var(--color-ink);
}

/* =========================================
   8. HERO INFORMATION STRIP
   ========================================= */

.hero-bottom {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 2;
  border-top: 1px solid rgba(255, 255, 255, 0.24);
  background: rgba(28, 33, 29, 0.58);
  backdrop-filter: blur(8px);
}

.hero-bottom-inner {
  display: flex;
  width: min(
    calc(100% - (var(--page-gutter) * 2)),
    var(--container-width)
  );
  min-height: 76px;
  margin-inline: auto;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}

.hero-detail {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: rgba(255, 255, 255, 0.88);
  font-size: var(--text-sm);
}

.hero-detail strong {
  color: var(--color-white);
  font-weight: 700;
}

/* =========================================
   9. SECONDARY CONTACT PROMPT
   ========================================= */

.hero-contact {
  display: inline-flex;
  align-items: center;
  gap: 0.7rem;
  color: var(--color-white);
  font-size: var(--text-sm);
  font-weight: 600;
}

.hero-contact:hover {
  color: #e6b18a;
}

.hero-contact a {
  text-decoration: underline;
  text-decoration-color: rgba(255, 255, 255, 0.45);
  text-underline-offset: 4px;
}

/* =========================================
   10. TABLET AND MOBILE HEADER
   ========================================= */

@media (max-width: 1100px) {
  .header-inner {
    gap: 1rem;
  }

  .primary-navigation ul {
    gap: 1rem;
  }

  .header-phone {
    display: none;
  }

  .site-brand img {
    max-width: 165px;
  }
}

@media (max-width: 900px) {
  :root {
    --nav-height: 76px;
  }

  .header-inner {
    position: relative;
    min-height: var(--nav-height);
  }

  .menu-toggle {
    display: inline-flex;
    order: 3;
  }

  .header-actions {
    margin-left: auto;
  }

  .primary-navigation {
    position: absolute;
    top: 100%;
    right: 0;
    left: 0;
    display: none;
    max-height: calc(100svh - var(--nav-height) - 1rem);
    align-items: stretch;
    overflow-y: auto;
    padding: 1rem var(--page-gutter) 1.5rem;
    border-top: 1px solid var(--color-border);
    background: var(--color-white);
    box-shadow: var(--shadow-elevated);
  }

  .primary-navigation.is-open {
    display: flex;
    flex-direction: column;
  }

  .primary-navigation ul {
    width: 100%;
    align-items: stretch;
    flex-direction: column;
    gap: 0;
  }

  .primary-navigation li {
    width: 100%;
    border-bottom: 1px solid var(--color-border);
  }

  .primary-navigation a,
  .nav-dropdown > button {
    display: flex;
    width: 100%;
    min-height: 50px;
    justify-content: space-between;
    padding: 0.5rem 0;
    font-size: var(--text-base);
  }

  .nav-dropdown-menu {
    position: static;
    display: none;
    width: 100%;
    padding: 0 0 0.5rem 1rem;
    border: 0;
    background: transparent;
    box-shadow: none;
  }

  .nav-dropdown:hover .nav-dropdown-menu,
  .nav-dropdown:focus-within .nav-dropdown-menu,
  .nav-dropdown-menu.is-open {
    display: block;
  }

  .nav-dropdown-menu a {
    min-height: 44px;
    font-size: var(--text-sm);
  }

  .primary-navigation .mobile-nav-contact {
    margin-top: 1rem;
    border: 0;
  }

  .primary-navigation .mobile-nav-contact a {
    min-height: 50px;
    justify-content: center;
    padding: 0.8rem 1rem;
    border-radius: var(--radius-small);
    background: var(--color-accent);
    color: var(--color-white);
    font-weight: 700;
  }
}

